  "dbdump.import": "Importer i en fersk database",
  "dbdump.importConfirm": "Importere denne {engine} {version}-dumpen i {container}? BombVault stopper containeren, flytter datamappen dens til side (den beholdes, ingenting slettes), starter containeren med en tom datamappe og importerer dumpen. Programmene som bruker denne databasen, ser tilstanden fra da dumpen ble tatt.",
  "dbdump.importConfirmNoVersion": "Importere denne {engine}-dumpen i {container}? BombVault stopper containeren, flytter datamappen dens til side (den beholdes, ingenting slettes), starter containeren med en tom datamappe og importerer dumpen. Programmene som bruker denne databasen, ser tilstanden fra da dumpen ble tatt.",
