  "mcp.oauthToggle": "Pålogging via OAuth",
  "mcp.oauthHint": "For ChatGPT, Claude på claude.ai og andre tjenester som ikke kan ta en nøkkel. De sender deg til en BombVault-side der du logger på med innloggingspassordet ditt og gir dem tillatelse. De kaller BombVault fra sine egne servere, så BombVault må kunne nås fra internett på den offentlige adressen nedenfor, med et sertifikat som nettlesere stoler på. Slår du den av, logges alle klienter av.",
