  "anomaly.settings.title": "Avvik",
  "anomaly.settings.hint": "Sammenligner hver sikkerhetskopi av et element med elementets egen historikk og melder det som ikke passer. Kjører i bakgrunnen etter hver sikkerhetskopi og gjør ingen tregere. De fleste sjekkene starter etter 10 sikkerhetskopier av et element; feil, omskriving av det meste av dataene og en nesten tom kilde sjekkes fra starten av. Ledig plass overvåkes for lokale repositorier og for rclone-repositorier som oppgir den; på Unraids brukerdeling er det den ledige plassen i hele arrayet.",
  "anomaly.settings.toggle": "Oppdag avvik",
