  "whatsNew.notesTab": "Utgivelsesnotater",
  "whatsNew.hint": "Hva oppdateringene brakte, ett kort per utgivelse. En lysende prikk markerer hver endring på siden sin, og et klikk på en prikk skjuler den. En prikk på en fane, en flis eller en rad forsvinner når du har sett alt bak den.",
