  "whatsNew.page.entry": "Siden til et element",
  "whatsNew.page.location": "Siden til et mål",
  "whatsNew.page.none": "I bakgrunnen",
  "whatsNew.windowTitleSince": "Nytt siden {version}",
  "whatsNew.overviewHead": "Grønne prikker markerer det som er nytt. Et klikk skjuler en prikk, og under Innstillinger, Info står de alle.",
  "whatsNew.overviewCustomize": "Oversikten starter med fem kort. Flere venter under «Tilpass», og hvert kort kan flyttes, endres i størrelse og skjules.",
  "whatsNew.overviewDecline": "«Ikke sikkerhetskopier» tar et element ut av denne listen når du med vilje lar det stå utenfor. Det teller da ikke lenger som ubeskyttet.",
  "whatsNew.overviewInstances": "I Android-appen viser toppen av oversikten navnet på instansen du er på. Pilen foran navnet tar deg tilbake til appens oversikt, der alle instansene dine står.",
  "whatsNew.backupsTiles": "Alt som sikkerhetskopieres står i én liste. Flisene velger en type.",
  "whatsNew.backupsBar": "«Filtre», «Sorter» og «Søk» er tre knapper over listen.",
  "whatsNew.backupsRow": "En rad viser én status, og resten står i boblen ved siden av navnet. Velg rader som filer: Ctrl+klikk, Shift+klikk eller et langt trykk.",
  "whatsNew.backupsActions": "Hovedhandlingen på en side flyter nederst til høyre. «Mer» rommer de sjeldne.",
  "whatsNew.entryPage": "Hvert element har sin egen side med tre faner: Sikkerhetskopier, Innstillinger og Verifisering.",
  "whatsNew.entryDefaults": "Et element følger standard tidsplan og standardmål til det får sine egne her.",
  "whatsNew.restoreTiles": "«Gjenoppretting» er én side for alt. Velg et område eller søk etter et element, og velg så en sikkerhetskopi på tidslinjen.",
  "whatsNew.restoreWhere": "Ett vindu spør hva som skal gjenopprettes og hvor. «Ved siden av originalen» henter tilbake en kopi og lar originalen være som den er.",
  "whatsNew.restoreMany": "Velg flere elementer med Ctrl+klikk, Shift+klikk eller et langt trykk, og gjenopprett dem sammen, ett etter ett.",
  "whatsNew.restoreEmergency": "Her starter nødveiviseren. Den henter tilbake en server som er borte eller satt opp på nytt, i fire trinn.",
  "whatsNew.anomaliesTiles": "Flisene velger alvorlighetsgrad. «Åpent» eller «Lukket» velger listen.",
  "whatsNew.anomaliesRings": "En ring per element viser hvor langt oppdagelsen har lært hva som er normalt.",
  "whatsNew.storageList": "Lokale og eksterne mål står i én liste. Hvert mål har sin egen side.",
  "whatsNew.storageFlow": "3-2-1 som bilde. Hver linje fra et område til et mål er en bryter, også Lokal, og ett klikk slår den på eller av. Et område viser hvor mange av elementene sine som sikres et annet sted.",
  "whatsNew.locationKeep": "Oppbevaring er «Kort», «Balansert», «Lang» eller dine egne verdier. Tidslinjen viser hvilke sikkerhetskopier en regel beholder.",
  "whatsNew.locationMove": "«Flytt» tar kopien av et område med til et annet mål, med hele historikken.",
  "whatsNew.instancesPair": "Instanser pares med tolv ord. Deretter viser hver av dem rollene sine som fliser.",
  "whatsNew.instancesPhones": "Telefoner som er koblet til via Android-appen, får et eget kort ved siden av instansene.",
  "whatsNew.settingsTiles": "Innstillinger er fjorten fliser. Trykk / eller Ctrl+K for å søke i alle, også etter navnene sidene hadde før.",
  "whatsNew.settingsPin": "Mål og Instanser er fliser i innstillingene. Denne bryteren fester dem til sidefeltet.",
  "whatsNew.settingsWeek": "Uken som et bånd, med hver planlagte kjøring fra mandag til søndag.",
  "whatsNew.pairingSteps": "Tre kort viser hvordan paring fungerer. Under dem har relayen fire former, hver med sitt bilde.",
  "whatsNew.settingsVersion": "Info rommer Versjon, Hjelp og Om appen. Versjon viser BombVault, GlimStone, restic og rclone. Knappen Nytt der åpner listen over endringer, eller utgivelsesnotatene når du har sett dem alle.",
  "whatsNew.settingsManual": "Den gule knappen under Hjelp åpner håndboken.",
